//===- mac_mode.cc ----------------------------------------------*- C++ -*-===//
//
// probe capture kernel for MAC config mode (1, 3, 3) `conv_16x4`
// (GENERATED by tools/gen_mac_modes.py). Per tile and signedness flavour (ss, su, us,
// uu; first letter is A) it runs mul_conv_16x4.
// Chunk layout: 2 operand blocks of T tiles (A, B).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

#include <aie_api/aie.hpp>

#define T 32
#define OUT_WORDS_PER_TILE 128

#define STORE(r, dst) \
  do { aie::accum<acc64, 16> w(r); aie::store_v((dst), w.to_vector<int32>(0)); aie::store_v((dst) + 16, w.to_vector<int32>(32)); } while (0)

extern "C" {

void mac_mode(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 64;
  // Read the 64-bit lanes as two 32-bit halves: srs by 0 and by 32 with no saturation.
  aie::set_saturation(aie::saturation_mode::none);
  aie::set_rounding(aie::rounding_mode::floor);
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // ss
      v32int16 v0 = *(v32int16 *)(in0 + n * 64);
      v32int16 v1 = *(v32int16 *)(in1 + n * 64);
      v16acc64 r0 = mul_conv_16x4(v0, v1);
      STORE(r0, o + 0);
    }
    { // su
      v32int16 v0 = *(v32int16 *)(in0 + n * 64);
      v32uint16 v1 = *(v32uint16 *)(in1 + n * 64);
      v16acc64 r0 = mul_conv_16x4(v0, v1);
      STORE(r0, o + 32);
    }
    { // us
      v32uint16 v0 = *(v32uint16 *)(in0 + n * 64);
      v32int16 v1 = *(v32int16 *)(in1 + n * 64);
      v16acc64 r0 = mul_conv_16x4(v0, v1);
      STORE(r0, o + 64);
    }
    { // uu
      v32uint16 v0 = *(v32uint16 *)(in0 + n * 64);
      v32uint16 v1 = *(v32uint16 *)(in1 + n * 64);
      v16acc64 r0 = mul_conv_16x4(v0, v1);
      STORE(r0, o + 96);
    }
  }
  event1();
}

} // extern "C"
